code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(grid[i][0] for i in range(h) if all(v == grid[i][0] and v != 0 for v in grid[i]))
    rs = list(range(0, h, 5))
    cs = list(range(0, w, 5))
    mr = mc = None
    for r in rs:
        for c in cs:
            cells = [(i, j) for i in range(r, min(r+4, h))
                     for j in range(c, min(c+4, w)) if grid[i][j] not in (0, divider)]
            if len(cells) > 4:
                mr, mc = r, c
                break
        if mr is not None:
            break
    motif = [[grid[mr+i][mc+j] not in (0, divider) for j in range(4)] for i in range(4)]
    out = [row[:] for row in grid]
    for r in rs:
        if r + 3 >= h:
            continue
        color = next((grid[i][j] for i in range(r, r+4) for j in range(4)
                      if grid[i][j] not in (0, divider)), 0)
        for c in cs:
            if c + 3 >= w:
                continue
            for i in range(4):
                for j in range(4):
                    out[r+i][c+j] = color if motif[i][j] else 0
    return out
'''
